const f = document.querySelector('iframe') ? document.querySelector('iframe').contentDocument : document;
const adol = f.getElementById('listbox-adolesence'); adol.value='0'; adol.dispatchEvent(new Event('change',{bubbles:true}));
const fc = f.getElementById('listbox-first-crime'); fc.value='1'; fc.dispatchEvent(new Event('change',{bubbles:true}));
const lc = f.getElementById('listbox-last-crime'); lc.value='0'; lc.dispatchEvent(new Event('change',{bubbles:true}));
const hc = f.getElementById('listbox-pc-haircolor'); hc.value='2'; hc.dispatchEvent(new Event('change',{bubbles:true}));
const r = f.getElementById('radiobutton-pc-photo-index-0'); r.checked=true; r.dispatchEvent(new Event('change',{bubbles:true}));
return JSON.stringify({a:adol.value,c:fc.value,l:lc.value,h:hc.value});

const passages = SugarCube.Story.passages();
const names = Object.keys(passages).filter(n => /downtown|gang|mafia|cartel|biker|warehouse|bank/i.test(n));
return JSON.stringify(names.sort());

