const areas = [...document.querySelectorAll('area')].map(a => ({
  passage: a.getAttribute('data-passage') || a.dataset.passage,
  coords: a.coords,
  shape: a.shape,
  alt: a.alt,
  href: a.href
}));
return JSON.stringify(areas);

